function m(e,r,t){return Math.min(Math.max(e,r),t)}function h(e,r){let t=e.length;if(r==null){let n=e.reduce((u,a)=>u+a)/t}return Math.sqrt(e.map(n=>Math.pow(n-r,2)).reduce((n,u)=>n+u)/t)}function b(e){return e.reduce((r,t)=>r+t)/e.length}function i(e=0,r=1){let t=1-Math.random(),n=Math.random();return Math.sqrt(-2*Math.log(t))*Math.cos(2*Math.PI*n)*r+e}function l(e,r,t){let n=[];for(let u=e;u<r;u+=t)n.push(u);return n}function c(e,r,t){let n=(r-e)/(t-1);return l(e,r+n,n)}function p(e,r,t=!1){let n=[],u=l(0,e.length,1);if(t)for(let a=0;a<r;a++)n.push(e[u[Math.floor(Math.random()*u.length)]]);else for(let a=0;a<r;a++){let o=Math.floor(Math.random()*u.length);n.push(e[o]),u.splice(o,1)}return n}export{m as a,h as b,b as c,i as d,c as e,p as f};
